UPDATE lessons SET title='Year 4, Week 36, Lesson 2: Researching and planning', data=json_patch(data,'{"child_mission":"Researching and planning gathers ideas, constraints (time, materials, safety) and a step timeline before building a STEM project.","coming_soon":null,"duration_minutes":55,"evidence_instructions":"Save the independent response, specific revisions and both short-answer explanations; record oral evidence for speaking tasks.","explicit_teaching":null,"extension":"Apply the same science idea to a new object or material, then compare two pieces of evidence for strength.","follow_up_challenges":null,"guided_practice":"PRACTISE BEFORE READING THE FEEDBACK\nList three constraints that should appear in a Year 4 STEM plan and why time matters.\n\nFEEDBACK\nMaterials/safety/time (or skills); time limits unfinished safe builds.\n\nWATCH FOR\nSkipping research repeats failed ideas already known.","hoard_words":null,"independent_task":"INDEPENDENT EVIDENCE\nProduce a project plan: research notes, constraints, materials list, three-milestone timeline and risk/safety note.\n\nWrite a short reflection naming one observation or step you corrected and why.","interactive_activities":null,"learning_area":"Science and Technology","learning_intention":"Researching and planning gathers ideas, constraints (time, materials, safety) and a step timeline before building a STEM project.","lesson_number":2,"lesson_role":"Apply and make","materials":["Paper or typed answer space","Pencil","Optional: safe everyday objects for observation"],"offline_alternative":"Use paper and pencil to complete the original task, then retain a photograph or short parent observation as evidence.","outcome_codes":["ST2-DDT-02"],"parent_notes":"Parent: Marking guidance for the independent task: Produce a project plan: research notes, constraints, materials list, three-milestone timeline and risk/safety note. Accept equivalent original responses that show the same skill.\n\nParent: Written model 1: Sample: new object/context, two named observations, claim about research linked to that evidence.\n\nParent: Written model 2: Sample misconception: Skipping research repeats failed ideas already known.. Correction: Materials/safety/time (or skills); with evidence.\n\nParent: Likely misconception: Skipping research repeats failed ideas already known. Keep sample answers out of the child role.\n\nParent: Short-answer focus 1: Investigate or describe a fresh example (not the worked objects) that uses research. Record evidence and explain how it supports your claim.\n\nParent: Short-answer focus 2: Name one science misconception about research, correct it with evidence, and say why the correction works.\n\nParent: Marking notes: Accept a new example with named observations and a claim–evidence link about research. Reject title-only labels with no observation. / Accept a misconception plus corrected claim and evidence reason for research. Reject wording changes that leave the same error..","pass":1,"pass_mark":0.9,"planner_fields":null,"planner_intro":null,"planner_title":null,"printable_resource":null,"quiz":[{"correct_index":2,"explanation":"This matches the taught method for research. The other choices miss a key step or use a common mistake.","options":["A claim that names no evidence from the lesson material","A method that skips the key step taught in this lesson","Materials/safety/time (or skills)","Skipping research repeats failed ideas already known"],"question":"List three constraints that should appear in a Year 4 STEM plan and why time matters. Which response is most accurate?","type":"multiple_choice"},{"correct_index":3,"explanation":"This is the misconception to avoid for research; the other choices align with the lesson method. The other choices miss a key step or use a common mistake.","options":["Researching and planning gathers ideas, constraints (time, materials, safety) and a step timeline before building a","Materials/safety/time (or skills)","Careful use of plan and explain why it matters with clear evidence","Skipping research repeats failed ideas already known"],"question":"Which statement is a common mistake when working with research?","type":"multiple_choice"},{"correct_index":0,"explanation":"Understanding is shown by new evidence and a named plan and explain why it matters, not by copying the model. The other choices miss a key step or use a common mistake.","options":["Apply research to new material and name the plan and explain why it matters used","Repeat the worked example wording with no new evidence","Skipping research repeats failed ideas already known","Name plan and explain why it matters only, without linking it to research"],"question":"Which response best applies research with new evidence?","type":"multiple_choice"},{"correct_index":2,"explanation":"Trustworthy science claims rest on observable evidence linked to the claim. The other choices miss a key step or use a common mistake.","options":["Copy a label from the lesson title with no observation","Skipping research repeats failed ideas already known","Use observable features or measurements as evidence, not appearance alone","Decide from which object looks most exciting"],"question":"New examples: steam from a kettle, a germinating bean, a plastic dinosaur, a granite pebble. Which claim about research is most trustworthy?","type":"multiple_choice"},{"correct_index":3,"explanation":"Science claims need named observations linked to the claim. The other choices miss a key step or use a common mistake.","options":["A longer story with no observation","A label copied from the title with no evidence","Skipping research repeats failed ideas already known","A named observation plus how it supports the claim"],"question":"Which record best supports a science claim about research?","type":"multiple_choice"},{"correct_index":0,"explanation":"The strongest choice applies the taught idea about research with evidence. The other choices miss a key step or use a common mistake.","options":["Materials/safety/time (or skills)","Skipping research repeats failed ideas already known","Change several conditions at once so something happens faster","Ignore measurements and decide by which looks nicer"],"question":"Using this science idea — Researching and planning gathers ideas, constraints (time, materials, safety) and a step timeline — which choice is strongest?","type":"multiple_choice"},{"correct_index":3,"explanation":"Fair tests change one variable, control the rest, and use recorded evidence. The other choices miss a key step or use a common mistake.","options":["Change several conditions at once so something happens faster","Stop early when you like the first result","Ignore measurements and decide by which looks nicer","Change one variable and keep the other conditions the same"],"question":"Which investigation design best tests an idea about research?","type":"multiple_choice"},{"correct_index":0,"explanation":"Scientific predictions stay open to new observations rather than protecting a first guess. The other choices miss a key step or use a common mistake.","options":["If the observed feature changes, the claim about research should change with it","Any exciting story about the object must be true","Skipping research repeats failed ideas already known","Results that disagree with the first guess should be discarded"],"question":"Which prediction about research can be checked with evidence?","type":"multiple_choice"},{"explanation":"Independent evidence on new material demonstrates the skill; copying the model does not.","marking_guide":"Accept a new example with named observations and a claim–evidence link about research. Reject title-only labels with no observation.","question":"Investigate or describe a fresh example (not the worked objects) that uses research. Record evidence and explain how it supports your claim.","sample_answer":"Sample: new object/context, two named observations, claim about research linked to that evidence.","type":"short_answer"},{"explanation":"A useful correction changes the inaccurate idea or method and explains why.","marking_guide":"Accept a misconception plus corrected claim and evidence reason for research. Reject wording changes that leave the same error.","question":"Name one science misconception about research, correct it with evidence, and say why the correction works.","sample_answer":"Sample misconception: Skipping research repeats failed ideas already known.. Correction: Materials/safety/time (or skills); with evidence.","type":"short_answer"}],"resources":null,"response_prompt":"Include your independent evidence and reflection, with reasons where requested.","review_status":"unreviewed","seed_key":"s2-sci-y4-w36-l2","sort_activity":null,"source_note":"Proposed Stage 2 NESA Science and Technology alignment using catalogue outcome codes; content-point mapping remains pending.","spelling":null,"spelling_focus":null,"stage":"S2","stage_hints":{"accept":["Today you will practise research.","Read the mission before you start observing or testing.","Keep the property or variable you are studying in view."],"guided":["Attempt the guided prompt without looking ahead.","Afterwards, compare your evidence with the feedback.","Adjust anything that does not match the method."],"learn":["Study how the first demonstration is built.","Point to the observation or step that carries the idea.","Then write the reason without copying every sentence."],"quiz":["Read every option before you choose.","Eliminate answers that ignore observations or fair tests.","Prefer accurate evidence over a guess that merely looks neat."],"submit":["Confirm that your evidence and reason are both present.","Proofread labels, measurements and sequence of steps.","Make sure the final evidence matches the lesson purpose."],"teach0":["Read the stage title and find the worked model.","Name one exact observation or test step before you decide.","Try the small prompt before opening the comparison."],"teach1":["Return to the model and list the key observations.","Say what each observation shows about the idea.","A final label alone is weaker than recorded evidence."],"teach2":["Compare a weak claim with stronger evidence.","Change the claim or method, not only how neat the drawing looks.","Name the mistake you are repairing."],"teach3":["Choose a fresh object or context that still uses the same skill.","Write one reason in your own words.","Do not retype the worked model as your answer."],"write":["Follow every part of the independent instructions.","Include original evidence and a short reason.","Save work that shows the skill on new objects or data."]},"subject":"Working Scientifically and Technologically","success_criteria":["I can use research with a specific example from this lesson.","I can identify plan and explain why it matters.","I can practise constraint independently on a new prompt.","I can notice resource needs and correct a likely mistake."],"suspense_builder":null,"teach_steps":[{"check":{"correct_index":3,"explanation":"Researching and planning gathers ideas, constraints (time, materials, safety) and a step timeline before building a STEM project.","options":["A claim unrelated to the observation or test","An answer copied without understanding","A guess with no evidence","Researching and planning gathers ideas, constraints (time, materials, safety) and a step timeline before building a"],"question":"Which choice best applies this lesson idea about research with clear evidence?","type":"multiple_choice"},"example":"WORKED MODEL\nResearch: existing bag hooks/clips. Constraints: cardboard only; two lessons to build. Plan: sketch → prototype → test.\n\nTRY FIRST\nList three constraints that should appear in a Year 4 STEM plan and why time matters.\n\nFEEDBACK\nMaterials/safety/time (or skills); time limits unfinished safe builds.","explain":"Researching and planning gathers ideas, constraints (time, materials, safety) and a step timeline before building a STEM project.\n\nWHY IT MATTERS\nThis helps the learner base claims on observation, fair tests and design evidence, rather than guessing from a picture alone. Keep every claim linked to what was seen or measured.\n\nHOW TO WORK\nRead the worked example and name the observations, properties or test steps that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. Compare your record with the feedback: did you use the same skill and show your evidence? If a result is uncertain, identify what would have to be observed or tested again. One deliberate, evidence-based revision is more useful than writing a longer answer.","icon":"📖","notice":"Skipping research repeats failed ideas already known. Correct the claim or method, not just the neatness of the diagram.","title":"Understand and model","visual":[{"alt":"Project planning.","caption":"Time is a constraint.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Research</text><text x=\"28\" y=\"78\">constraints</text><text x=\"358\" y=\"42\">Timeline</text><text x=\"358\" y=\"78\">milestones</text></g></svg>"}],"visual_before":[{"episode":{"scenes":[{"bg":"room","lines":[{"text":"I can see the example, but I am not sure which observation matters most.","who":"pip"},{"text":"Name the observations, properties or test steps that carry the idea before you decide.","who":"juno"},{"text":"I will try the prompt myself, then compare with the feedback.","who":"pip"},{"pause_after":true,"text":"Pause here. Use this model: Research: existing bag hooks/clips. Constraints: cardboard only; two lessons to build. Plan: sketch → prototype → test. Then write your own evidence.","who":"juno"}]}],"title":"Talk through the first model","transcript":"Pip: I can see the example, but I am not sure which observation matters most.\nJuno: Name the observations, properties or test steps that carry the idea before you decide.\nPip: I will try the prompt myself, then compare with the feedback.\nJuno: Pause here. Use this model: Research: existing bag hooks/clips. Constraints: cardboard only; two lessons to build. Plan: sketch → prototype → test. Then write your own evidence."}}]},{"check":{"correct_index":1,"explanation":"Make the science idea visible: name the observation, source or example you used and say why it supports the claim.","options":["An answer copied without understanding","Make the science idea visible: name the observation, source or example you used and say why it supports the claim","A guess with no evidence","A claim unrelated to the observation or test"],"question":"Which choice best applies this lesson idea about research with clear evidence?","type":"multiple_choice"},"example":"WORKED MODEL\nResearch: existing bag hooks/clips. Constraints: cardboard only; two lessons to build. Plan: sketch → prototype → test. Look at each observation, source detail or example that carries the idea.\n\nTRY FIRST\nList the key observations, sources or steps from the model and say what each one shows.\n\nFEEDBACK\nThe most useful record names the evidence and the reason it supports the claim, not only a label.","explain":"Make the science idea visible: name the observation, source or example you used and say why it supports the claim.\n\nWHY IT MATTERS\nThis helps the learner base claims on observation, fair tests and design evidence, rather than guessing from a picture alone. Keep every claim linked to what was seen or measured.\n\nHOW TO WORK\nRead the worked example and name the observations, properties or test steps that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. Compare your record with the feedback: did you use the same skill and show your evidence? If a result is uncertain, identify what would have to be observed or tested again. One deliberate, evidence-based revision is more useful than writing a longer answer.","icon":"📖","notice":"Writing only a final label without evidence does not show science thinking. Correct the claim or method, not just the neatness of the diagram.","title":"Show the evidence","visual":[{"alt":"Three milestones.","caption":"Full plan.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Plan page</text><text x=\"28\" y=\"78\">risks noted</text><text x=\"358\" y=\"42\">Risk</text><text x=\"358\" y=\"78\">skip research</text></g></svg>"}]},{"check":{"correct_index":1,"explanation":"Use an intentionally incorrect claim as a comparison.","options":["An answer copied without understanding","Use an intentionally incorrect claim as a comparison","A guess with no evidence","A claim unrelated to the observation or test"],"question":"Which choice best applies this lesson idea about research with clear evidence?","type":"multiple_choice"},"example":"WORKED MODEL\nSkipping research repeats failed ideas already known. Here is a more productive model: Research: existing bag hooks/clips. Constraints: cardboard only; two lessons to build. Plan: sketch → prototype → test.\n\nTRY FIRST\nDescribe why the warned-against claim fails, then write a corrected claim with evidence.\n\nFEEDBACK\nMaterials/safety/time (or skills); time limits unfinished safe builds.","explain":"Use an intentionally incorrect claim as a comparison. Name its specific science error, then show the corrected evidence-based claim.\n\nWHY IT MATTERS\nThis helps the learner base claims on observation, fair tests and design evidence, rather than guessing from a picture alone. Keep every claim linked to what was seen or measured.\n\nHOW TO WORK\nRead the worked example and name the observations, properties or test steps that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. Compare your record with the feedback: did you use the same skill and show your evidence? If a result is uncertain, identify what would have to be observed or tested again. One deliberate, evidence-based revision is more useful than writing a longer answer.","icon":"📖","notice":"Changing the wording without repairing the evidence does not fix the error. Skipping research repeats failed ideas already known. Correct the claim or method, not just the neatness of the diagram.","title":"Test a misconception"},{"check":{"correct_index":2,"explanation":"Use the same science idea on a new place, person, source or context, not a copy of the worked example.","options":["A guess with no evidence","A claim unrelated to the observation or test","Use the same science idea on a new place, person, source or context, not a copy of the worked example","An answer copied without understanding"],"question":"Which choice best applies this lesson idea about research with clear evidence?","type":"multiple_choice"},"example":"WORKED MODEL\nResearching and planning gathers ideas, constraints (time, materials, safety) and a step timeline before building a STEM project. Now choose a different example to show you can transfer the idea.\n\nTRY FIRST\nInquire into or describe one fresh example that uses the same skill and write a short evidence-based reason.\n\nFEEDBACK\nThe new example should use the same science idea as the model, but contain different evidence.","explain":"Use the same science idea on a new place, person, source or context, not a copy of the worked example. Review accuracy of evidence.\n\nWHY IT MATTERS\nThis helps the learner base claims on observation, fair tests and design evidence, rather than guessing from a picture alone. Keep every claim linked to what was seen or measured.\n\nHOW TO WORK\nRead the worked example and name the observations, properties or test steps that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. Compare your record with the feedback: did you use the same skill and show your evidence? If a result is uncertain, identify what would have to be observed or tested again. One deliberate, evidence-based revision is more useful than writing a longer answer.","icon":"📖","notice":"Repeating the worked example cannot show transfer to new evidence. Correct the claim or method, not just the neatness of the diagram.","title":"Transfer to a new investigation"}],"title":"Year 4, Week 36, Lesson 2: Researching and planning","unit_number":8,"unit_title":"Stage 2 STEM project","week":36,"week_in_unit":1,"word_challenges":null,"worked_example":"WORK THROUGH THIS\nResearch: existing bag hooks/clips. Constraints: cardboard only; two lessons to build. Plan: sketch → prototype → test.\n\nWrite what makes this example accurate, naming the observations, properties or test steps used.","worked_visuals":[{"alt":"Project planning.","caption":"Time is a constraint.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Research</text><text x=\"28\" y=\"78\">constraints</text><text x=\"358\" y=\"42\">Timeline</text><text x=\"358\" y=\"78\">milestones</text></g></svg>"},{"alt":"Three milestones.","caption":"Full plan.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Plan page</text><text x=\"28\" y=\"78\">risks noted</text><text x=\"358\" y=\"42\">Risk</text><text x=\"358\" y=\"78\">skip research</text></g></svg>"}],"year_level":"Year 4"}') WHERE seed_key='s2-sci-y4-w36-l2' AND family_id IS NULL;
